using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra;
internal sealed class LatticeHalfFockCorrectedMonodromyDocument : IScribeDocumentDefinition
{
 private const string Prefix = "D5/S3/VertexAlgebra/LatticeHalfFockCorrectedMonodromy.";
 private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/VertexAlgebra/bakalovkac2004lattice");
 public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
 "Coordinate Monodromy of Every Corrected Source", H("Coordinate Monodromy of Every Corrected Source"), Blocks(
 Paragraph(Text("Let D:LatticeData be any finite-rank integral symmetric even lattice and hu:IsUnit D.G.det. The ordinary source Carrier D is the finite charge sum of algebraic oscillator polynomials. The target ActualTensor D hu is the original oscillator algebra tensor the actual quotient ground module. All integer exponents, zero charges, rank zero, indefinite Gram matrices, repeated oscillators, inhomogeneous sources and arbitrary target tensors remain in scope.")),
 Paragraph(Text("The actual quotient ground action identifies charge a and -a by reduction modulo two. The creation logarithm and translated polynomial have only odd coordinate frequencies. Charge negation therefore gives chargedCoefficient(-a,e)=(-1)^e smul chargedCoefficient(a,e), using the even norm B(a,a). No inverse ground-action substitution is used.")),
 Describe.Lean(DescribeId.Create("normal-polynomial-coordinate-monodromy"), DeclarationHandle.Create(Prefix + "normal_polynomial_coordinate_monodromy"), H("Normal polynomial parity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
 Blocks(Paragraph(Text("For every D:LatticeData, hu:IsUnit D.G.det, a:Charge D, p:Oscillator D and e:Int, (polynomialField D hu (-a) (sigma D p)).coeff e = ((-1:Complex)^e) smul (polynomialField D hu a p).coeff e, as endomorphisms of ActualTensor D hu. Each word coefficient factors through the charged coefficient at e+2*modeSum+jetShift. The parity of jetShift is the word length. sigma multiplies a monomial by the same word-length sign, and the two signs cancel. The native pointwise finite-support theorem justifies the mode sum separately at every target vector; no finite End-valued mode support is claimed."))), DescribeRole.Theorem),
 Describe.Lean(DescribeId.Create("finite-correction-sigma"), DeclarationHandle.Create(Prefix + "Corr_sigma"), H("Equivariance of the original finite correction"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
 Blocks(Paragraph(Text("For every D:LatticeData, a:Charge D and p:Oscillator D, Corr D (-a) (sigma D p) = Finsupp.mapRange.linearMap (sigmaLinear D) (Corr D a p). The correction lift fixes X none and negates X(some i). It fixes the pair polynomial, anticommutes with each pair derivation, and takes insertion at a to minus insertion at -a. Word induction gives exactly the monomial sign of sigma. optionEquivLeft carries the lift to Polynomial.map sigma without a shift-dependent sign. The correction is linear and is not treated as an algebra homomorphism."))), DescribeRole.Theorem),
 Describe.Lean(DescribeId.Create("full-corrected-field-theta"), DeclarationHandle.Create(Prefix + "correctedField_theta"), H("The full source theta identity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
 Blocks(Paragraph(Text("For every D:LatticeData, hu:IsUnit D.G.det, u:Carrier D and e:Int, (LatticeHalfFockCorrectedField.correctedField D hu (LatticeInvolution.theta D u)).coeff e = ((-1:Complex)^e) smul (LatticeHalfFockCorrectedField.correctedField D hu u).coeff e. This is equality in Module.End Complex (ActualTensor D hu). The field, correctedPolynomial, correctedSum and shiftField are precisely those defined in LatticeHalfFockOriginalTranslation. The canonical shift has coefficient A.coeff(e+2*s), and (-1)^(e+2*s)=(-1)^e for every signed e and natural s. Finite correction extensionality followed by finite-charge linear-map extensionality and theta_single proves the equality. There is no action of theta on the target and no eigenstate or pure-tensor restriction."))), DescribeRole.Theorem),
 Paragraph(Text("Classical provenance: Frenkel-Lepowsky-Meurman (1988); Dong-Nagatomo math/9808088v1 section 3.2, pp.12-14; Bakalov-Kac math/0402315v1 (4.4), (4.23)-(4.38). The normal parity, shift-fixing correction lift and full theta argument follow the preserved CorrectedField proposal; the charged argument is supplied by LatticeHalfFockChargedMonodromy. The canonical original-translation source supplies all field constructors. Inherited half-Fock implementation copyright (c) 2025 Kalle Kytola; additional half-integer implementation copyright (c) 2026; Apache 2.0. Finite support architecture follows VirasoroProject 5ff4245383b2cdd4eea7a0524bc1274c32041eb4 and PolynomialFock bfd9ff0f15397a4fb933f36d701a60d325d84b08. No literature novelty is asserted.")),
 Paragraph(Text("This coordinate identity is one ingredient for a twisted vertex-operator construction. All-source locality and source-product identities, twisted Jacobi and Borcherds, conformal and positive-energy structure, analytic sewing, fusion and anomalies, orbifold and Monster/Moonshine realization, complete string dynamics and the AdS/CFT bridge remain further obligations.")))));
}
